    def Q(topic, suffix, prompt, answer, example, kind='open', **extra):
        t=by_id[topic]
        q=dict(id=topic+'-'+suffix,lesson=0,topic=topic,framework=t['framework'],collection='tooling',
               type=kind,level='reason',prompt=prompt,answer=answer,example=example,source=deepcopy(t['source']))
        if kind=='open':q['rubric']=extra.pop('rubric',['Назван механизм и нужный API','Обоснован результат на данных задачи','Указано ограничение или способ проверки'])
        q.update(extra);questions.append(q)

    # Three distinct conceptual exercises per topic; code exercises are appended below.
    conceptual = [
      ('lt-module','Почему loss.item() в training_step не заменяет возвращаемый loss tensor?', 'item() возвращает Python-число без autograd-графа. Automatic optimization нужен differentiable scalar loss; для отображения можно логировать отдельно.', 'Скалярный tensor с grad_fn сохраняет связь с параметрами, float — нет.'),
      ('lt-module','validation_step посчитал loss. Почему веса от этого не обновились?', 'Validation измеряет качество без train-оптимизации. Нет optimizer step; стандартный validation loop также отключает обучение и autograd для обычной проверки.', 'Число .2 в val_loss не является командой уменьшить веса.'),
      ('lt-module','Линейная модель w=1, x=2, y=0; loss=(wx−y)², SGD lr=.1. Найдите новое w.', 'Производная 2(wx−y)x=8, новое w=1−.1·8=.2.', 'Один шаг automatic optimization должен воспроизвести это при обычном SGD.', 'number',dict(value=.2,tolerance=1e-6,calculation=r'w_{new}=1-0.1\cdot 2(1\cdot2)2=0.2')),
      ('lt-logging','Батчи val имеют размеры 4 и 1, средние loss 1 и 6. Какой epoch loss по объектам?', 'Взвешенное среднее равно (4·1+1·6)/5=2.', 'Среднее двух средних 3.5 ошибочно для среднего по пяти объектам.', 'number',dict(value=2,tolerance=0,calculation=r'\bar L=(4\cdot1+1\cdot6)/5=2')),
      ('lt-logging','Можно ли получить dataset F1 усреднением F1 каждого батча?', 'В общем случае нельзя: F1 нелинеен по TP,FP,FN. Накопите эти статистики по датасету, затем вычислите F1; в DDP сведите статистики.', 'Батчи с разным количеством положительных примеров имеют разные знаменатели.'),
      ('lt-logging','Что именно делает prog_bar=True в self.log?', 'Показывает метрику в progress bar; сохранение во внешний logger регулирует logger=True.', 'Число на экране и историческая запись — разные выходы.', 'single',dict(options=['Выводит метрику в progress bar','Сохраняет лучший checkpoint','Выполняет backward','Автоматически вычисляет accuracy'],correct=[0])),
      ('lt-data','Почему train_dataset нельзя создавать только в prepare_data?', 'Этот hook не предназначен для создания состояния на каждом процессе. Создавайте Dataset/split в setup; prepare_data оставьте подготовке файлов.', 'В DDP другой процесс может не получить атрибут self.train_dataset.'),
      ('lt-data','Какие проверки помогают избежать утечки validation?', 'Индексы train/val не пересекаются, зависимые объекты делятся по группам, статистики препроцессинга учатся только на train.', 'Разные кадры одного пациента могут утечь даже при разных индексах.', 'multi',dict(options=['Проверить пересечение train/val','Делить зависимые кадры по видео/пациенту','Подобрать нормализацию по всему test','Выбирать split с максимальным val accuracy после десятков попыток'],correct=[0,1])),
      ('lt-data','seed_everything вызван, но версии CUDA и GPU поменялись. Обязано ли всё совпасть бит в бит?', 'Нет. Seed управляет RNG, но алгоритмы, устройства, версии и nondeterministic операции могут отличаться. Фиксируйте среду и проверяйте требуемую воспроизводимость.', 'Одинаковый seed — часть протокола, а не полное описание окружения.'),
      ('lt-optimization','10 train-батчей за эпоху, accumulate_grad_batches=4. Сколько optimizer updates при полном проходе?', 'Три: после групп 4,4,2.', 'Остаток тоже даёт обновление.', 'number',dict(value=3,tolerance=0,calculation=r'U=\lceil10/4\rceil=3')),
      ('lt-optimization','Microbatch=8, accumulation=4, DDP processes=2. Каков эффективный размер полной группы?', '8·4·2=64 объекта.', 'Это размер градиентной группы; BatchNorm по-прежнему видит локальный microbatch.', 'number',dict(value=64,tolerance=0,calculation=r'B_{eff}=8\cdot4\cdot2=64')),
      ('lt-optimization','Зачем в manual optimization нужен self.manual_backward вместо обычного loss.backward?', 'Он учитывает настроенные Lightning precision/strategy. Но zero_grad, порядок оптимизаторов и step в manual режиме задаёт пользователь.', 'Нельзя одновременно ожидать автоматические шаги и выполнять свои без ясного режима.'),
      ('lt-checkpoint','Что выбрать: load_from_checkpoint или fit(ckpt_path=...), если нужно продолжить Adam после сбоя?', 'fit с ckpt_path восстанавливает состояние цикла и оптимизатора. load_from_checkpoint создаёт модель с весами/hparams для дальнейшего использования; это не полное восстановление Trainer.', 'У Adam одинаковые веса с разными моментами дают разные следующие шаги.'),
      ('lt-checkpoint','EarlyStopping patience=3, проверка раз в 2 эпохи. Три проверки подряд без улучшения: сколько эпох между исходной и третьей такой проверкой?', 'Шесть эпох при указанной регулярной частоте.', 'Patience считает проверки monitor, а не train-батчи.', 'number',dict(value=6,tolerance=0,calculation=r'3\cdot2=6')),
      ('lt-checkpoint','val_loss=.8,.4,.6. Что верно про best и last?', 'Best относится ко второй эпохе, last к третьей. EarlyStopping не обязан автоматически восстановить best.', 'Для финальной оценки явно выберите best_model_path.', 'multi',dict(options=['best относится ко второй эпохе','last относится к третьей эпохе','EarlyStopping всегда загружает лучшие веса','Сохранения только весов достаточно для полного resume Adam'],correct=[0,1])),
      ('lt-loggers','Можно ли одним self.log доставить метрику в TensorBoard и MLflow?', 'Да: передать оба logger в списке Trainer(logger=[...]). Но предварительно проверьте run и смысл step каждого получателя.', 'Публикация значения одна, получателей два.'),
      ('lt-loggers','Чем callback ModelCheckpoint отличается от TensorBoardLogger?', 'Callback реагирует на события и сохраняет состояние модели по критерию; logger записывает наблюдения/метрики. Наличие графика не означает наличие checkpoint.', 'Из loss-графика веса восстановить нельзя.'),
      ('lt-loggers','Какой объект возвращает MLFlowLogger.experiment?', 'MlflowClient. Его методы требуют явный run_id там, где это предусмотрено API клиента.', 'logger.experiment.log_metric(logger.run_id, key, value, step=...) отличается от fluent mlflow.log_metric.', 'single',dict(options=['MlflowClient','Обычный Python dict с loss','PyTorch optimizer','Fluent-модуль mlflow без run_id'],correct=[0])),
      ('tb-events','Почему add_scalar вызван, но новая точка ещё не видна?', 'Проверьте правильный log_dir, наличие event-файла, буфер writer и обновление UI. flush/close помогают дождаться записи.', 'Не нужно переобучать сеть только из-за не обновившегося dashboard.'),
      ('tb-events','Как расположить папки для двух независимых экспериментов?', 'Разные дочерние папки, например runs/a и runs/b, а TensorBoard читает runs.', 'Так одинаковый tag Loss/train не смешивает точки двух run.', 'single',dict(options=['runs/a и runs/b; logdir=runs','Оба всегда пишут в один runs/a','Один файл весов .pt вместо event-файлов','Логирование только через print'],correct=[0])),
      ('tb-events','Чем flush отличается от checkpoint?', 'flush сбрасывает события writer на диск, checkpoint сохраняет состояние модели/обучения. События не содержат автоматически все веса.', 'Можно успешно закрыть writer и всё равно потерять веса, если их не сохраняли.'),
      ('tb-scalars','e=1, b=3, 10 батчей в эпохе, индексы с нуля. Найдите сквозной batch step.', '1·10+3=13.', 'Для optimizer step при accumulation нужна другая ось.', 'number',dict(value=13,tolerance=0,calculation=r's=1\cdot10+3=13')),
      ('tb-scalars','Почему batch_idx как global_step внутри каждой эпохи искажает общий график?', 'batch_idx начинается заново. Точки разных эпох получают одинаковые X. Используйте сквозной счётчик или явно логируйте epoch-метрику по эпохам.', 'Точка epoch2/batch0 не должна возвращаться в X=0 на сквозном графике.'),
      ('tb-scalars','Сглаживание убрало всплеск loss. Изменились ли веса или исходные точки?', 'Нет. Это преобразование отображения. Проверяйте исходные значения и причины всплеска.', 'Красивый график не означает, что нестабильное обновление не происходило.'),
      ('tb-images','Изображение shape=(32,32,3). Как корректно записать add_image без перестановки осей?', 'Передать dataformats="HWC".', 'Форма CHW по умолчанию имеет иной смысл.', 'single',dict(options=['dataformats="HWC"','Всегда оставить CHW по умолчанию','Поменять RGB на BGR','Сначала flatten всего массива'],correct=[0])),
      ('tb-images','x_norm=(x−.5)/.25. Какое исходное x соответствует x_norm=−1?', 'x=−1·.25+.5=.25.', 'Восстановление диапазона делают на display-копии.', 'number',dict(value=.25,tolerance=1e-6,calculation=r'x=-1\cdot0.25+0.5=0.25')),
      ('tb-images','Почему permute HWC→CHW не исправит синее небо, ставшее красным из-за BGR?', 'permute переставляет оси, а BGR/RGB — порядок значений внутри канальной оси. Нужна отдельная перестановка каналов.', 'Форма (3,H,W) одинаково допустима для ошибочного и правильного порядка цветов.'),
      ('tb-histograms','Можно ли из одинаковой гистограммы двух feature map заключить, что они равны?', 'Нет: гистограмма теряет расположение элементов.', '[-1,1] и [1,-1] имеют одинаковые частоты.'),
      ('tb-histograms','Когда логировать градиенты, чтобы увидеть градиент текущего шага?', 'После backward и до очистки градиентов; понимать, до/после clipping сделан снимок.', 'После zero_grad(set_to_none=True) .grad может быть None.'),
      ('tb-histograms','Нулевые градиенты однозначно доказывают слишком маленький learning rate?', 'Нет. LR масштабирует обновление, а нули могут возникать из-за графа, активаций или отсутствия участия параметра. Нужно проверить путь loss к параметру.', 'Веса могут не изменяться по нескольким причинам, гистограмма — только наблюдение.'),
      ('tb-embeddings','Матрица embedding [100,64]. Сколько metadata-подписей нужно?', '100, по одной на строку.', '64 — размер признака, не число объектов.', 'number',dict(value=100,tolerance=0,calculation=r'|\mathrm{metadata}|=N=100')),
      ('tb-embeddings','labels=[1,0,1], scores=[.9,.8,.2], порог .5. Чему равен precision?', 'TP=1, FP=1, precision=.5.', 'Recall здесь тоже .5: один из двух положительных найден.', 'number',dict(value=.5,tolerance=0,calculation=r'P=1/(1+1)=0.5')),
      ('tb-embeddings','Почему в add_pr_curve лучше подать scores, а не результат scores>.5?', 'Пороговые классы теряют ранжирование и почти все возможные operating points. PR-кривая должна менять порог по непрерывным scores.', 'Scores .51 и .99 после threshold становятся одинаковой единицей.'),
      ('tb-hparams','3 LR, 2 batch size, 4 seed. Сколько запусков в полном переборе?', '3·2·4=24.', 'Число trials — произведение, а не сумма вариантов.', 'number',dict(value=24,tolerance=0,calculation=r'N=3\cdot2\cdot4=24')),
      ('tb-hparams','Запустит ли add_hparams обучение для каждой конфигурации?', 'Нет. Он записывает конфигурацию и метрики уже выполненного trial; цикл обучения/поиска нужно организовать отдельно.', 'Таблица результатов сама не является оптимизатором гиперпараметров.'),
      ('tb-hparams','Какие условия нужны для честного сравнения HParams trials?', 'Единый validation-протокол и отдельные run для конфигураций; test оставляют для итоговой оценки.', 'Сравнение не должно вознаграждать случайно удобный split.', 'multi',dict(options=['Одинаковое правило validation','Отдельный run_name на trial','Подбирать LR по test accuracy','Логировать train loss одного trial как val loss другого'],correct=[0,1])),
      ('mf-runs','Почему sqlite:///training.db из другой рабочей папки показывает пустой experiment?', 'Относительный путь разрешается от текущей папки; создан или открыт другой файл базы. Используйте известную рабочую папку или абсолютный URI.', 'Одинаковая строка относительного URI не гарантирует одинаковый файл.'),
      ('mf-runs','Два run_name="baseline". Должны ли совпадать run_id?', 'Нет. Имя не обязано быть уникальным; идентификатор отличает run.', 'Сохраняйте run_id для точной ссылки.', 'single',dict(options=['Нет, это разные run с разными ID','Да, имя является первичным ключом','Да, если один seed','Run вообще не имеет ID'],correct=[0])),
      ('mf-runs','Что произойдёт с контекстным run, если внутри with start_run выброшено исключение?', 'Контекст завершит run с неуспешным статусом и передаст исключение дальше; ошибка не становится успешным обучением.', 'Для сравнения выбирайте FINISHED и проверяйте наличие итоговой метрики.'),
      ('mf-metadata','Почему нельзя логировать изменяющийся scheduler LR через log_param("lr", ...)?', 'Param фиксируется в run, повторное другое значение запрещено. Логируйте initial_lr как param, текущий lr как metric со step.', 'История LR — временной ряд, а не перезапись конфига.'),
      ('mf-metadata','Какие значения разумно сохранить для воспроизводимости?', 'Seed, split_id/правило разбиения, commit и версии среды. Метрики без контекста недостаточны.', 'Seed=7 не сообщает, какие примеры попали в val.', 'multi',dict(options=['Seed и split_id','Commit и версии библиотек','Только лучшее accuracy','Только красивое имя run'],correct=[0,1])),
      ('mf-metadata','В каком виде MLflow RunData.params возвращает числовой batch_size?', 'Как строку, например "32". Для арифметики преобразуйте тип осознанно.', 'Строковая сортировка "100" и "32" отличается от числовой.', 'single',dict(options=['Строкой','Всегда torch.Tensor','Всегда numpy.int64','Списком всех прошлых значений'],correct=[0])),
      ('mf-metrics','val_loss=.6,.2,.4 на step0,1,2. Чему равен best_val_loss?', '.2, минимум истории.', 'Сводное val_loss по последнему шагу равно .4.', 'number',dict(value=.2,tolerance=0,calculation=r'L_{best}=\min(0.6,0.2,0.4)=0.2')),
      ('mf-metrics','Как получить все точки val_loss, а не сводку в RunData.metrics?', 'MlflowClient.get_metric_history(run_id, "val_loss"); проверьте step и при необходимости отсортируйте.', 'Словарь metrics не заменяет историю.'),
      ('mf-metrics','Почему лучше логировать best_val_loss отдельно для search_runs?', 'Поиск по сводному val_loss не вычисляет минимум всех прошлых точек. Отдельная метрика выражает критерий выбора явно.', 'Run с .1→.8 может быть лучшим по минимуму и плохим по последнему значению.'),
      ('mf-artifacts','Сколько десятичных MB занимают 1 000 000 float32 весов без служебных данных?', '4 MB: миллион умножить на 4 байта.', 'Полный checkpoint включает больше, например Adam moments.', 'number',dict(value=4,tolerance=0,calculation=r'10^6\cdot4/10^6=4\ \mathrm{MB}')),
      ('mf-artifacts','Достаточно ли скопировать SQLite-базу для переноса всех MLflow artifacts?', 'Нет, artifact storage может находиться отдельно. Переносите базу и нужное содержимое artifact store с корректными URI.', 'В базе может быть ссылка на файл, которого на новом компьютере нет.'),
      ('mf-artifacts','Что отличается у log_artifact("weights.pt") и pytorch.log_model?', 'Первый сохраняет произвольный файл. Второй создаёт MLflow Model с flavor/описанием среды и интерфейсом; один файл весов не даёт этого автоматически.', 'Для загрузки state_dict ещё нужен класс модели.'),
      ('mf-models','Почему после загрузки обычного nn.Module из pickle всё ещё полезны eval() и inference_mode()?', 'eval переключает поведение Dropout/BatchNorm; inference_mode отключает autograd и связанные накладные расходы. Это разные механизмы.', 'Отключённый autograd сам по себе не переключает Dropout в eval.'),
      ('mf-models','Что следует сохранить из результата log_model для последующей загрузки?', 'ModelInfo.model_uri, возвращённый вызовом.', 'Он ссылается на конкретную сохранённую модель.', 'single',dict(options=['model_info.model_uri','Только красивое имя run','Последний val_loss','Число слоёв вместо URI'],correct=[0])),
      ('mf-models','Гарантирует ли signature высокое качество или полное восстановление обучения?', 'Нет. Signature описывает вход/выход; качество проверяет оценка, optimizer loop восстанавливает подходящий полный checkpoint.', 'Правильный dtype не делает классификатор точным.'),
      ('mf-comparison','Средние accuracy по seed: .7,.8,.9. Найдите среднее.', '.8.', 'Стандартное отклонение ddof=0 здесь примерно .08165, это не доверительный интервал.', 'number',dict(value=.8,tolerance=1e-6,calculation=r'\bar m=(0.7+0.8+0.9)/3=0.8')),
      ('mf-comparison','Какое направление сортировки выбрать для metrics.best_val_loss?', 'ASC, меньший loss лучше при одинаковом протоколе.', 'Для accuracy обычно DESC.', 'single',dict(options=['ASC','DESC всегда','Сортировать только по имени run','Сортировать по времени создания вместо метрики'],correct=[0])),
      ('mf-comparison','Почему лучший test accuracy среди 100 конфигураций — плохой способ выбрать LR?', 'Test участвует в выборе, возникает адаптация к нему. Подбирайте на validation, после выбора проведите отдельную итоговую test-оценку.', 'MLflow хранит результат, но не предотвращает статистическую утечку.'),
    ]
    for index, row in enumerate(conceptual):
        topic,prompt,answer,example,*tail=row
        kind=tail[0] if tail else 'open';extra=tail[1] if len(tail)>1 else {}
        Q(topic,'concept-'+str(index+1),prompt,answer,example,kind,**extra)

    def C(topic, key, focus, prompt, setup, code, result, why, trap, test, doc=None):
        t=by_id[topic];library=next(g['title'] for g in guides if g['id']==t['framework'])
        c=dict(id=key,library=library,topics=[topic],lesson=0,framework=t['framework'],collection='tooling',
               focus=focus,prompt=prompt,setup=setup,code=code,result=result,explanation=why,trap=trap,
               test=test,runtime='tooling',source=deepcopy(t['source']),basis='Дополнительная инженерная практика по официальной документации; не вопрос из ноутбука курса.',doc=doc or t['source']['url'])
        cards.append(c);t['codeCards'].append(key)
        Q(topic,'api-'+key,focus+'. '+prompt+'\n\nДано:\n```python\n'+setup+'\n```',
          '```python\n'+code+'\n```\n\n'+why+'\n\nРезультат: '+result,trap,'open',level='apply',codeCard=key)
        if 'implementation' not in t:
            t['implementation']=dict(language='python',code=setup+'\n\n'+code,note=focus+'. '+why,source=deepcopy(t['source']))

    # Every cell has explicit setup and one central operation. Integration tests execute the exact strings.
    C('lt-module','lt-loss','training_step: differentiable loss','Реализуйте training_step для одного batch; верните MSE без item().',
      'import torch\nimport lightning.pytorch as pl\n\nclass LitReg(pl.LightningModule):\n    def __init__(self):\n        super().__init__()\n        self.layer = torch.nn.Linear(1, 1, bias=False)\n        torch.nn.init.ones_(self.layer.weight)\n\n    def forward(self, x):\n        return self.layer(x)\n\nmodel = LitReg()\nbatch = (torch.tensor([[2.]]), torch.tensor([[0.]]))',
      'def training_step(self, batch, batch_idx):\n    x, y = batch\n    return torch.nn.functional.mse_loss(self(x), y)\n\nLitReg.training_step = training_step\nloss = model.training_step(batch, 0)',
      'Скалярный tensor loss=4 с autograd-графом.', 'MSE сравнивает прогноз с target; tensor сохраняет путь градиента к layer.weight.',
      'Присваивание метода в примере лишь позволяет показать одну функцию отдельно; в проекте поместите её внутрь класса.',
      'assert loss.ndim == 0 and loss.requires_grad\nloss.backward()\ntorch.testing.assert_close(model.layer.weight.grad, torch.tensor([[8.]]))')
    C('lt-module','lt-optimizer','configure_optimizers','Подключите SGD с lr=.1 к параметрам модели.',
      'import torch\nimport lightning.pytorch as pl\n\nclass LitReg(pl.LightningModule):\n    def __init__(self):\n        super().__init__()\n        self.layer = torch.nn.Linear(1, 1)\n\nmodel = LitReg()',
      'def configure_optimizers(self):\n    return torch.optim.SGD(self.parameters(), lr=0.1)\n\nLitReg.configure_optimizers = configure_optimizers\noptimizer = model.configure_optimizers()',
      'Optimizer содержит параметры layer и learning rate .1.', 'Trainer вызывает этот hook, чтобы получить правило обновления.', 'Создание optimizer не выполняет шаг и не считает loss.',
      'assert optimizer.param_groups[0]["lr"] == 0.1\nassert {id(p) for p in optimizer.param_groups[0]["params"]} == {id(p) for p in model.parameters()}')
    C('lt-logging','lt-log','self.log: weighted epoch loss','Добавьте в validation_step запись среднего val_loss по объектам.',
      'import torch\nimport lightning.pytorch as pl\n\nclass ValModel(pl.LightningModule):\n    def __init__(self):\n        super().__init__()\n        self.anchor = torch.nn.Parameter(torch.tensor(0.))',
      'def validation_step(self, batch, batch_idx):\n    x, y = batch\n    loss = (x - y).square().mean()\n    self.log("val_loss", loss, on_step=False, on_epoch=True,\n             batch_size=x.size(0), logger=True)\n\nValModel.validation_step = validation_step',
      'После validation лог содержит среднее по объектам, а не невзвешенное среднее батчей.', 'batch_size задаёт вес каждого batch mean при epoch reduction.', 'Метод нужно вызывать через Trainer, иначе контекст epoch-агрегации отсутствует.',
      'from torch.utils.data import DataLoader, TensorDataset\nx = torch.tensor([[1.],[1.],[1.],[1.],[6.**0.5]])\nloader = DataLoader(TensorDataset(x, torch.zeros_like(x)), batch_size=4)\ntrainer = pl.Trainer(logger=False, enable_checkpointing=False, enable_progress_bar=False)\ntrainer.validate(ValModel(), dataloaders=loader, verbose=False)\nassert abs(float(trainer.callback_metrics["val_loss"]) - 2.) < 1e-5')
    C('lt-logging','lt-logdict','self.log_dict: именованные метрики','Запишите val_loss и val_mae на уровне эпохи.',
      'import torch\nimport lightning.pytorch as pl\n\nclass ValPair(pl.LightningModule):\n    pass',
      'def validation_step(self, batch, batch_idx):\n    x, y = batch\n    error = x - y\n    self.log_dict({"val_loss": error.square().mean(),\n                   "val_mae": error.abs().mean()},\n                  on_step=False, on_epoch=True, batch_size=x.size(0))\n\nValPair.validation_step = validation_step',
      'Две независимые epoch-метрики с общим весом batch.', 'Словарь сокращает одинаковую настройку нескольких скаляров.', 'MAE и MSE имеют разные единицы и не должны быть одной серией.',
      'from torch.utils.data import DataLoader, TensorDataset\nx = torch.tensor([[2.],[2.]])\ntrainer = pl.Trainer(logger=False, enable_checkpointing=False, enable_progress_bar=False)\ntrainer.validate(ValPair(), DataLoader(TensorDataset(x, torch.zeros_like(x)), batch_size=2), verbose=False)\nassert float(trainer.callback_metrics["val_loss"]) == 4\nassert float(trainer.callback_metrics["val_mae"]) == 2')
    C('lt-data','lt-seed','seed_everything','Сбросьте RNG так, чтобы повторить следующий torch.rand на CPU.',
      'import torch\nimport lightning.pytorch as pl\npl.seed_everything(7, workers=True)\nfirst = torch.rand(3)',
      'pl.seed_everything(7, workers=True)\nsecond = torch.rand(3)',
      'first и second совпадут в этой среде.', 'Повторная установка seed возвращает генератор к началу той же последовательности.', 'Это не доказательство совпадения всех CUDA-операций между разными версиями.', 'torch.testing.assert_close(first, second)')
